package ifElse;

public class LargestOf3Number {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a=100, b=200,c=30;

		if(a>b && a>c)
		{
			System.out.println("a is largest number is "+a);
		}
		else if(b>a && b>c) {

		System.out.println("b is largest number is "+b);
		}
		else{
			System.out.println("c is largest number is "+c);
			}


	}

}
